UPDATE public.items SET explanation = '{"text_fr":"La fonction $x \\mapsto x^2$ est polynômiale, donc continue en tout point de $\\mathbb{R}$. Quand une fonction est continue en un point $a$, sa limite y vaut simplement $f(a)$ — la substitution directe est valide. Application : $\\lim_{x \\to 0} x^2 = 0^2 = 0$.","steps":["Vérifier la continuité : $x^2$ est un polynôme, continu partout.","Substituer $x = 0$ directement : $0^2 = 0$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000001';
UPDATE public.items SET explanation = '{"text_fr":"Quand $x$ tend vers $+\\infty$, le numérateur 1 reste fixe alors que le dénominateur $x$ devient arbitrairement grand. Une fraction de la forme « constante / quelque chose qui tend vers l''infini » tend toujours vers 0. Cette limite est l''archétype de la décroissance vers zéro à l''infini.","steps":["Comportement du dénominateur : $x \\to +\\infty$.","Numérateur fixe = 1, dénominateur diverge → ratio tend vers 0."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000002';
UPDATE public.items SET explanation = '{"text_fr":"Le polynôme $x^2 + 1$ est continu sur $\\mathbb{R}$ (somme de monômes), donc on peut substituer directement la valeur $x = 3$ pour obtenir la limite. Calcul : $3^2 + 1 = 9 + 1 = 10$. Toujours essayer la substitution directe avant de chercher des techniques avancées.","steps":["Polynôme continu en 3.","$3^2 + 1 = 9 + 1 = 10$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000003';
UPDATE public.items SET explanation = '{"text_fr":"La fonction affine $2x + 5$ est continue partout, on substitue donc directement $x = 2$. Calcul : $2 \\cdot 2 + 5 = 4 + 5 = 9$. Pour toute fonction affine $ax + b$ et tout point $c$, la limite est $ac + b$ — pas de subtilité.","steps":["Continuité de l''affine $2x + 5$.","Évaluation directe : $2(2) + 5 = 9$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000004';
UPDATE public.items SET explanation = '{"text_fr":"La définition de la limite $\\lim_{x \\to a} f(x) = L$ exprime que $f(x)$ se rapproche autant qu''on veut de $L$ quand $x$ se rapproche de $a$. **Cela ne dit rien sur $f(a)$ — la fonction peut très bien ne pas être définie en $a$, ou y prendre une autre valeur.** L''égalité $f(a) = L$ ne tient que si $f$ est continue en $a$.","steps":["La limite décrit le comportement *près de* $a$, pas *en* $a$.","Continuité = limite égale à la valeur — c''est une condition supplémentaire."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000005';
UPDATE public.items SET explanation = '{"text_fr":"Quand $x$ se rapproche de 0, l''inverse $1/x$ tend vers $\\pm\\infty$, donc $\\sin(1/x)$ oscille de $-1$ à $+1$ infiniment souvent. La fonction ne se rapproche d''aucune valeur particulière : la limite **n''existe pas**. Les autres options ont une limite bien définie : $0$, $1$ ou $0$.","steps":["$1/x \\to \\pm\\infty$ quand $x \\to 0$.","$\\sin(\\pm\\infty)$ oscille indéfiniment dans $[-1, 1]$.","Pas de valeur d''accumulation unique → pas de limite."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000006';
UPDATE public.items SET explanation = '{"text_fr":"$(x - 5)^2$ est un polynôme continu partout. On substitue $x = 5$ : $(5 - 5)^2 = 0^2 = 0$. Tout polynôme s''annule en ses racines ; ici la racine est double (multiplicité 2).","steps":["Polynôme continu en 5.","$(5-5)^2 = 0$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000007';
UPDATE public.items SET explanation = '{"text_fr":"Géométriquement, $f''(a)$ est la **pente de la tangente** à la courbe $y = f(x)$ au point d''abscisse $a$. Mathématiquement, c''est la limite du taux d''accroissement $\\dfrac{f(a+h) - f(a)}{h}$ quand $h \\to 0$ — c''est-à-dire la pente d''une corde infiniment courte, qui devient la tangente à la limite.","steps":["Taux d''accroissement = pente d''une corde sécante.","Limite du taux d''accroissement = pente de la tangente."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000008';
UPDATE public.items SET explanation = '{"text_fr":"Pour $f(x) = x^2$, on applique la règle $(x^n)'' = n x^{n-1}$ avec $n = 2$ : $f''(x) = 2x$. Cette règle vient directement de la définition par taux d''accroissement, mais on la mémorise. En $x = 3$ : $f''(3) = 2 \\cdot 3 = 6$.","steps":["Règle de dérivation : $(x^n)'' = n x^{n-1}$.","Application : $f''(x) = 2x$.","Évaluation en 3 : $f''(3) = 6$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000009';
UPDATE public.items SET explanation = '{"text_fr":"Une fonction affine $f(x) = ax + b$ a une dérivée constante égale au coefficient directeur $a$. Géométriquement, c''est cohérent : la courbe est elle-même une droite, donc la tangente coïncide avec la courbe et a la même pente partout. Pour $f(x) = 5x + 1$, $f''(x) = 5$ partout, et donc $f''(2) = 5$.","steps":["Dérivée d''une affine = coefficient directeur, constant.","$f''(x) = 5$ partout, donc $f''(2) = 5$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000000a';
UPDATE public.items SET explanation = '{"text_fr":"La définition formelle de la dérivée en un point $a$ est $f''(a) = \\lim_{h \\to 0} \\dfrac{f(a+h) - f(a)}{h}$. Le numérateur est la variation de la sortie, le dénominateur la variation de l''entrée ; le ratio est le taux d''accroissement moyen sur un intervalle de largeur $h$. À la limite $h \\to 0$, c''est la pente instantanée — c''est-à-dire la tangente.","steps":["Numérateur : $f(a+h) - f(a)$ = variation de $f$.","Dénominateur : $h$ = variation de $x$.","Limite = pente instantanée = dérivée."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000000b';
UPDATE public.items SET explanation = '{"text_fr":"Pour $f(x) = x^3$, la règle des puissances $(x^n)'' = n x^{n-1}$ donne $f''(x) = 3x^2$. Évaluation en $x = 2$ : $f''(2) = 3 \\cdot 4 = 12$. Cela signifie qu''au point $(2, 8)$ de la courbe, la tangente a une pente de 12.","steps":["$(x^3)'' = 3x^2$ par la règle des puissances.","$f''(2) = 3 \\cdot 4 = 12$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000000c';
UPDATE public.items SET explanation = '{"text_fr":"La pente de la tangente à $y = x^2$ au point $x = 1$ est $f''(1)$ avec $f(x) = x^2$. La dérivée est $f''(x) = 2x$, donc $f''(1) = 2$. La tangente complète a pour équation $y = 2(x-1) + 1 = 2x - 1$, mais ici la question ne demande que la pente.","steps":["$f''(x) = 2x$.","$f''(1) = 2$ — c''est la pente recherchée."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000000d';
UPDATE public.items SET explanation = '{"text_fr":"Pour $f(x) = 1/x = x^{-1}$, la règle des puissances généralisée $(x^n)'' = n x^{n-1}$ avec $n = -1$ donne $f''(x) = -x^{-2} = -\\dfrac{1}{x^2}$. Évaluation en 2 : $f''(2) = -1/4 = -0{,}25$. Cohérent avec le fait que $1/x$ est strictement décroissante : sa dérivée est partout négative.","steps":["$1/x = x^{-1}$.","Règle des puissances : $f''(x) = -x^{-2} = -1/x^2$.","En $x = 2$ : $f''(2) = -1/4 = -0{,}25$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000000e';
UPDATE public.items SET explanation = '{"text_fr":"Pour une suite arithmétique de premier terme $u_0$ et de raison $r$, le terme général est $u_n = u_0 + nr$ — chaque terme s''obtient en ajoutant $r$ depuis $u_0$, soit $n$ ajouts. Ici $u_0 = 2$ et $r = 3$, donc $u_{10} = 2 + 10 \\cdot 3 = 32$.","steps":["Formule : $u_n = u_0 + nr$.","Application : $u_{10} = 2 + 30 = 32$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000000f';
UPDATE public.items SET explanation = '{"text_fr":"Pour une suite géométrique de premier terme $u_0$ et de raison $q$, le terme général est $u_n = u_0 \\cdot q^n$ — chaque terme s''obtient en multipliant par $q$ depuis $u_0$, soit $n$ multiplications. Avec $u_0 = 1$ et $q = 2$ : $u_5 = 1 \\cdot 2^5 = 32$.","steps":["Formule : $u_n = u_0 \\cdot q^n$.","Application : $u_5 = 1 \\cdot 32 = 32$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000010';
UPDATE public.items SET explanation = '{"text_fr":"Une suite est arithmétique si la **différence** entre deux termes consécutifs est constante. Calcul : $7-3 = 4$, $11-7 = 4$, $15-11 = 4$. Différence constante de 4, donc arithmétique de raison $r = 4$. Le piège : confondre la valeur du premier terme (3) avec la raison.","steps":["Calcul des écarts consécutifs : tous valent 4.","Suite arithmétique de raison $r = 4$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000011';
UPDATE public.items SET explanation = '{"text_fr":"C''est la somme des entiers de 1 à 100, qu''on calcule par la **formule de Gauss** : $1 + 2 + \\dots + n = \\dfrac{n(n+1)}{2}$. Application avec $n = 100$ : $S = 100 \\cdot 101 / 2 = 5050$. La même formule s''écrit comme « (nombre de termes) × (premier + dernier) / 2 ».","steps":["Suite arithmétique 1, 2, ..., 100, raison 1.","Formule de Gauss : $S = n(n+1)/2 = 100 \\cdot 101 / 2 = 5050$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000012';
UPDATE public.items SET explanation = '{"text_fr":"Avec $|q| = 1/2 < 1$, la suite $u_n = 4 \\cdot (1/2)^n$ est **strictement décroissante** vers 0 : chaque terme vaut la moitié du précédent. Calcul : $u_0 = 4, u_1 = 2, u_2 = 1, u_3 = 0{,}5, ...$. Une suite géométrique avec $0 < q < 1$ et $u_0 > 0$ est toujours décroissante vers 0.","steps":["$|q| = 1/2 < 1$, on multiplie par moitié à chaque terme.","Décroissance vers 0."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000013';
UPDATE public.items SET explanation = '{"text_fr":"La somme $1 + 2 + 4 + 8 + 16$ est géométrique de raison $q = 2$ et premier terme $u_0 = 1$ avec **5 termes**. Formule générale : $S = u_0 \\cdot \\dfrac{1 - q^n}{1 - q}$ avec $n$ = nombre de termes. Application : $S = 1 \\cdot \\dfrac{1 - 32}{1 - 2} = \\dfrac{-31}{-1} = 31$.","steps":["Géométrique $q = 2$, 5 termes.","$S = (1 - 2^5)/(1 - 2) = (1-32)/(-1) = 31$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000014';
UPDATE public.items SET explanation = '{"text_fr":"Par définition même de la fonction logarithme népérien, $\\ln(1) = 0$. C''est la valeur qui justifie que $\\ln$ est l''unique primitive de $1/x$ sur $]0, +\\infty[$ s''annulant en 1. Géométriquement, c''est l''aire signée sous l''hyperbole $y = 1/t$ entre 1 et 1 — manifestement nulle.","steps":["Définition : $\\ln(1) = 0$.","Aussi : c''est la primitive de $1/x$ qui s''annule en 1."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000015';
UPDATE public.items SET explanation = '{"text_fr":"Le nombre $e$ est défini précisément comme **le réel tel que $\\ln(e) = 1$**. Numériquement, $e \\approx 2{,}718$. Cette définition fait de $\\ln$ et $\\exp = e^x$ deux fonctions réciproques l''une de l''autre. C''est aussi l''unique base $a$ pour laquelle la dérivée de $a^x$ en 0 vaut 1.","steps":["Définition : $e$ tel que $\\ln(e) = 1$.","$e \\approx 2{,}718$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000016';
UPDATE public.items SET explanation = '{"text_fr":"La propriété fondamentale du logarithme transforme un produit en somme : $\\ln(ab) = \\ln(a) + \\ln(b)$ pour $a, b > 0$. Cette propriété historique permettait d''utiliser des tables de logarithmes pour faire des multiplications difficiles (avant les calculatrices).","steps":["Règle : $\\ln(ab) = \\ln a + \\ln b$.","Vient de la définition intégrale de $\\ln$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000017';
UPDATE public.items SET explanation = '{"text_fr":"Par la propriété fondamentale appliquée à $a = (a/b) \\cdot b$, on obtient $\\ln a = \\ln(a/b) + \\ln b$, donc $\\ln(a/b) = \\ln a - \\ln b$. Le quotient se transforme en différence — c''est le pendant naturel de \"produit → somme\". Toujours valable pour $a, b > 0$.","steps":["Règle : $\\ln(a/b) = \\ln a - \\ln b$.","Conséquence directe de $\\ln(ab) = \\ln a + \\ln b$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000018';
UPDATE public.items SET explanation = '{"text_fr":"La fonction $\\ln$ est définie comme la primitive de $1/x$ sur $]0, +\\infty[$ s''annulant en 1. Le domaine de définition est donc $]0, +\\infty[$ — strictement positifs. Pour $x \\le 0$, $\\ln(x)$ n''a pas de sens en analyse réelle.","steps":["Domaine = $]0, +\\infty[$.","$\\ln$ n''existe pas pour $x \\le 0$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000019';
UPDATE public.items SET explanation = '{"text_fr":"La propriété fondamentale étendue aux puissances : $\\ln(a^n) = n \\ln a$ pour $a > 0$. Application : $\\ln(e^3) = 3 \\ln e = 3 \\cdot 1 = 3$. Plus généralement, $\\ln$ et $\\exp$ étant réciproques, $\\ln(e^x) = x$ pour tout réel $x$.","steps":["Règle : $\\ln(a^n) = n \\ln a$ ou $\\ln(e^x) = x$.","$\\ln(e^3) = 3$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000001a';
UPDATE public.items SET explanation = '{"text_fr":"Par définition, $e^0 = 1$. C''est cohérent avec la règle $a^0 = 1$ pour tout $a > 0$, et avec le fait que $\\exp(0) = 1$ (puisque $\\ln(1) = 0$ et $\\ln, \\exp$ sont réciproques).","steps":["$e^0 = 1$ par définition.","Confirme $\\exp(0) = 1$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000001b';
UPDATE public.items SET explanation = '{"text_fr":"La propriété fondamentale de l''exponentielle transforme la somme en produit : $e^{a+b} = e^a \\cdot e^b$. C''est l''analogue inverse de $\\ln(ab) = \\ln a + \\ln b$. Cette propriété fait de $\\exp$ un **homomorphisme** entre l''addition des réels et la multiplication des réels positifs.","steps":["Règle : $e^{a+b} = e^a \\cdot e^b$.","Inverse de $\\ln(ab) = \\ln a + \\ln b$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000001c';
UPDATE public.items SET explanation = '{"text_fr":"Par la propriété précédente avec $a + (-b) = a - b$ : $e^a = e^{(a-b)+b} = e^{a-b} \\cdot e^b$, donc $e^{a-b} = e^a / e^b$. La différence des exposants se traduit par un quotient — pendant naturel de la somme.","steps":["Règle : $e^{a-b} = e^a / e^b$.","Conséquence directe de $e^{a+b} = e^a e^b$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000001d';
UPDATE public.items SET explanation = '{"text_fr":"La dérivée de $e^x$ est elle-même : $(e^x)'' = e^x$. Comme $e^x > 0$ pour tout $x$, la dérivée est strictement positive partout, donc $e^x$ est **strictement croissante** sur tout $\\mathbb{R}$. C''est même la seule fonction qui croît plus vite que toute puissance polynomiale à l''infini.","steps":["$(e^x)'' = e^x > 0$ partout.","Donc $e^x$ strictement croissante sur $\\mathbb{R}$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000001e';
UPDATE public.items SET explanation = '{"text_fr":"Quand $x \\to -\\infty$, l''exponentielle décroît vers zéro par valeurs positives. Géométriquement, la courbe de $y = e^x$ admet l''axe des abscisses comme **asymptote horizontale à gauche**. C''est un cas limite : $e^x$ ne s''annule jamais, mais s''en approche autant qu''on veut.","steps":["$e^x \\to 0^+$ quand $x \\to -\\infty$.","Asymptote horizontale $y = 0$ à gauche."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000001f';
UPDATE public.items SET explanation = '{"text_fr":"$\\ln$ et $\\exp$ sont **fonctions réciproques** l''une de l''autre. Cela signifie que $\\ln(e^x) = x$ pour tout $x \\in \\mathbb{R}$, et symétriquement $e^{\\ln x} = x$ pour tout $x > 0$. Les deux fonctions « s''annulent » mutuellement.","steps":["$\\ln \\circ \\exp = \\mathrm{id}_\\mathbb{R}$.","$\\ln(e^x) = x$ pour tout $x$ réel."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000020';
UPDATE public.items SET explanation = '{"text_fr":"Pour identifier une primitive de $2x$, on cherche une fonction dont la dérivée vaut $2x$. La règle $(x^n)'' = n x^{n-1}$ avec $n = 2$ donne $(x^2)'' = 2x$ — exactement ce qu''on veut. Donc $x^2$ est primitive de $2x$. (Plus généralement, $x^2 + C$ pour toute constante $C$.)","steps":["Test : $(x^2)'' = 2x$ ✓.","Donc $x^2$ est primitive (à constante près)."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000021';
UPDATE public.items SET explanation = '{"text_fr":"La dérivée du logarithme népérien est $(\\ln x)'' = 1/x$ sur $]0, +\\infty[$. C''est cette définition qui donne $\\ln$ comme primitive naturelle de $1/x$. Sur les négatifs, il faut écrire $\\ln|x|$, mais ici $x > 0$ donc $\\ln x$ suffit.","steps":["$(\\ln x)'' = 1/x$.","Donc $\\ln x$ primitive de $1/x$ sur $]0, +\\infty[$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000022';
UPDATE public.items SET explanation = '{"text_fr":"On cherche une fonction dont la dérivée vaut $\\cos x$. La dérivée de $\\sin x$ est $\\cos x$ : $(\\sin x)'' = \\cos x$. Donc $\\sin x$ est primitive de $\\cos x$. Attention : la dérivée de $\\cos x$ est $-\\sin x$, pas l''inverse.","steps":["$(\\sin x)'' = \\cos x$.","Donc $\\sin x$ est primitive de $\\cos x$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000023';
UPDATE public.items SET explanation = '{"text_fr":"La fonction exponentielle est sa propre dérivée et donc sa propre primitive : $\\int e^x \\, dx = e^x + C$. C''est la propriété la plus remarquable de $e^x$ — elle motive toute son utilité dans les équations différentielles.","steps":["$(e^x)'' = e^x$.","Donc $e^x$ primitive d''elle-même."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000024';
UPDATE public.items SET explanation = '{"text_fr":"Si $F''(x) = f(x)$, alors $(F + 7)'' = F'' + 0 = f$ aussi — l''ajout d''une constante ne change rien à la dérivée. Donc $F + 7$ est aussi primitive de $f$. **Toutes les primitives d''une même fonction diffèrent d''une constante** — c''est pourquoi on écrit $+ C$ générique dans $\\int f \\, dx$.","steps":["(constante)'' = 0.","$(F+7)'' = F'' = f$.","Toute primitive est définie à constante près."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000025';
UPDATE public.items SET explanation = '{"text_fr":"Toute équation $y'' = ay$ où $a$ est une constante a pour solutions $y(x) = K e^{ax}$ avec $K \\in \\mathbb{R}$. Application avec $a = 2$ : $y = K e^{2x}$. Vérification : $y'' = 2K e^{2x} = 2y$ ✓. Le réel $K$ est déterminé par une condition initiale.","steps":["Forme $y'' = ay$ → solutions $K e^{ax}$.","Avec $a = 2$ : $y = K e^{2x}$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000026';
UPDATE public.items SET explanation = '{"text_fr":"Solution générale de $y'' = 3y$ : $y(x) = K e^{3x}$. Condition initiale $y(0) = 5$ : $K e^0 = K = 5$. Donc $y(x) = 5 e^{3x}$, et $y(1) = 5 e^3$. Numériquement, $e^3 \\approx 20{,}09$, donc $y(1) \\approx 100{,}4$.","steps":["Solution : $y = K e^{3x}$.","Condition initiale : $K = 5$.","$y(1) = 5 e^3 \\approx 100{,}4$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000027';
UPDATE public.items SET explanation = '{"text_fr":"On réécrit $y'' + 2y = 0$ comme $y'' = -2y$, qui est de la forme $y'' = ay$ avec $a = -2$. Solutions : $y = K e^{-2x}$. Le coefficient $-2$ produit une décroissance exponentielle (puisque $e^{-2x} \\to 0$ quand $x \\to +\\infty$).","steps":["Réécrire : $y'' = -2y$.","Solutions : $y = K e^{-2x}$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000028';
UPDATE public.items SET explanation = '{"text_fr":"L''équation $y'' = -y + 5$ a un second membre constant. Solution générale = solution homogène $K e^{-x}$ + solution particulière constante $y_p = 5$ (vérifiée par $0 + 5 = 5$). Donc $y(x) = K e^{-x} + 5$. La constante 5 est le **régime permanent**, vers lequel la solution converge.","steps":["Homogène : $K e^{-x}$.","Particulière constante : $y_p = 5$.","Total : $y = K e^{-x} + 5$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000029';
UPDATE public.items SET explanation = '{"text_fr":"Le nombre imaginaire $i$ est défini par la propriété fondamentale $i^2 = -1$. Cette définition étend l''algèbre des réels et permet de résoudre des équations comme $x^2 + 1 = 0$. Les complexes s''écrivent $a + ib$ avec $a, b$ réels.","steps":["Définition : $i^2 = -1$.","Permet d''inverser $x^2 + 1 = 0$ : $x = \\pm i$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000002a';
UPDATE public.items SET explanation = '{"text_fr":"Le module d''un complexe $z = a + ib$ vaut $|z| = \\sqrt{a^2 + b^2}$ — c''est la distance du point d''affixe $z$ à l''origine. Pour $z = 3 + 4i$ : $|z| = \\sqrt{9 + 16} = \\sqrt{25} = 5$. C''est l''archétype du triangle 3-4-5.","steps":["Formule : $|z| = \\sqrt{a^2+b^2}$.","$|3+4i| = \\sqrt{25} = 5$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000002b';
UPDATE public.items SET explanation = '{"text_fr":"Le conjugué d''un complexe $z = a + ib$ est $\\bar z = a - ib$ — on inverse le signe de la partie imaginaire en gardant la partie réelle. Pour $z = 2 - 3i$, le conjugué est $\\bar z = 2 + 3i$. Le conjugué reflète $z$ par rapport à l''axe réel dans le plan complexe.","steps":["Règle : $\\overline{a+ib} = a - ib$.","$\\overline{2-3i} = 2+3i$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000002c';
UPDATE public.items SET explanation = '{"text_fr":"Le produit $(1+i)(1-i)$ est de la forme $(a+b)(a-b) = a^2 - b^2$ avec $a = 1$, $b = i$. Donc $(1+i)(1-i) = 1 - i^2 = 1 - (-1) = 2$. **C''est le produit d''un complexe par son conjugué, qui vaut toujours $|z|^2$ — réel positif.**","steps":["Identité $(a+b)(a-b) = a^2 - b^2$.","$1 - i^2 = 1 + 1 = 2$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000002d';
UPDATE public.items SET explanation = '{"text_fr":"Pour $z = 0 + 5i$ (purement imaginaire), $|z| = \\sqrt{0^2 + 5^2} = \\sqrt{25} = 5$. Géométriquement, le point d''affixe $5i$ est sur l''axe imaginaire à distance 5 de l''origine. **Pour un imaginaire pur $ib$, le module vaut $|b|$.**","steps":["$|0 + 5i| = \\sqrt{0 + 25} = 5$.","Axe imaginaire pur : module = valeur absolue."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000002e';
UPDATE public.items SET explanation = '{"text_fr":"L''addition de deux complexes se fait coordonnée par coordonnée : $(a + ib) + (c + id) = (a+c) + i(b+d)$. Application : $(2+i) + (3-2i) = (2+3) + i(1-2) = 5 - i$. C''est l''addition vectorielle dans le plan complexe.","steps":["Règle : sommer parties réelles et parties imaginaires séparément.","$(2+3) + i(1-2) = 5 - i$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000002f';
UPDATE public.items SET explanation = '{"text_fr":"Le produit scalaire en dimension 3 est $\\vec u \\cdot \\vec v = u_1 v_1 + u_2 v_2 + u_3 v_3$. Application : $1 \\cdot 2 + 2 \\cdot (-1) + 3 \\cdot 1 = 2 - 2 + 3 = 3$. Géométriquement, $\\vec u \\cdot \\vec v = |\\vec u| |\\vec v| \\cos\\theta$.","steps":["Formule : $\\sum u_i v_i$.","$2 - 2 + 3 = 3$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000030';
UPDATE public.items SET explanation = '{"text_fr":"Si $\\vec u \\cdot \\vec v = 0$ et que ni $\\vec u$ ni $\\vec v$ ne sont nuls, alors $\\cos\\theta = 0$ donc $\\theta = \\pi/2$ : les deux vecteurs sont **orthogonaux** (perpendiculaires). C''est le critère le plus utilisé pour tester l''orthogonalité en pratique.","steps":["$\\vec u \\cdot \\vec v = 0 \\Rightarrow \\cos\\theta = 0\\Rightarrow \\theta = 90°$.","Vecteurs orthogonaux."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000031';
UPDATE public.items SET explanation = '{"text_fr":"La norme d''un vecteur en 3D est $\\|\\vec u\\| = \\sqrt{u_1^2 + u_2^2 + u_3^2}$, version 3D du théorème de Pythagore. Pour $\\vec u = (2, -2, 1)$ : $\\sqrt{4 + 4 + 1} = \\sqrt{9} = 3$.","steps":["Formule de Pythagore en 3D.","$\\sqrt{4+4+1} = 3$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000032';
UPDATE public.items SET explanation = '{"text_fr":"Le produit vectoriel $\\vec u \\wedge \\vec v$ produit un **vecteur orthogonal** au plan engendré par $\\vec u$ et $\\vec v$, de norme $|\\vec u||\\vec v|\\sin\\theta$, avec une orientation donnée par la règle de la main droite. C''est l''outil de référence pour construire des vecteurs perpendiculaires à un plan donné.","steps":["Produit vectoriel = vecteur orthogonal au plan formé.","Orientation par règle de la main droite."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000033';
UPDATE public.items SET explanation = '{"text_fr":"Le nombre de **permutations** (rangements ordonnés) de $n$ éléments distincts est $n!$ (factorielle). Pour $n = 5$ : $5! = 5 \\cdot 4 \\cdot 3 \\cdot 2 \\cdot 1 = 120$. Chaque rangement diffère par l''ordre des éléments.","steps":["Permutations de $n$ éléments = $n!$.","$5! = 120$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000034';
UPDATE public.items SET explanation = '{"text_fr":"Le coefficient binomial $\\binom{n}{k} = \\dfrac{n!}{k!(n-k)!}$ compte le nombre de **combinaisons** (sous-ensembles non ordonnés) de taille $k$ dans un ensemble de taille $n$. Application : $\\binom{6}{2} = \\dfrac{720}{2 \\cdot 24} = \\dfrac{720}{48} = 15$.","steps":["Formule : $\\binom{n}{k} = n!/(k!(n-k)!)$.","$\\binom{6}{2} = 720/48 = 15$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000035';
UPDATE public.items SET explanation = '{"text_fr":"La factorielle $n!$ représente le **produit décroissant** $n \\cdot (n-1) \\cdot (n-2) \\cdots 2 \\cdot 1$. C''est le nombre de façons d''ordonner $n$ objets distincts. Convention : $0! = 1$ (par cohérence avec les formules combinatoires).","steps":["Définition : $n! = n \\cdot (n-1) \\cdots 1$.","Convention : $0! = 1$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000036';
UPDATE public.items SET explanation = '{"text_fr":"Le nombre d''**arrangements** de $k$ éléments parmi $n$ (rangements ordonnés sans répétition) est $A_n^k = \\dfrac{n!}{(n-k)!} = n(n-1)(n-2)\\cdots(n-k+1)$. Application : $A_5^3 = 5 \\cdot 4 \\cdot 3 = 60$. C''est l''ordre qui distingue les arrangements des combinaisons.","steps":["Formule : $A_n^k = n!/(n-k)!$.","$A_5^3 = 5 \\cdot 4 \\cdot 3 = 60$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000037';
UPDATE public.items SET explanation = '{"text_fr":"$\\binom{4}{3} = \\dfrac{4!}{3! \\cdot 1!} = \\dfrac{24}{6} = 4$. Astuce : $\\binom{n}{k} = \\binom{n}{n-k}$, donc $\\binom{4}{3} = \\binom{4}{1} = 4$ — choisir 3 parmi 4 revient à choisir lequel des 4 on EXCLUT.","steps":["$\\binom{4}{3} = \\binom{4}{1} = 4$.","Choisir lequel exclure."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000038';
UPDATE public.items SET explanation = '{"text_fr":"On dit que $a$ divise $b$ s''il existe un entier $k$ tel que $b = a \\cdot k$. Test : $45 / 15 = 3$, qui est entier. Donc $15$ divise $45$, avec $45 = 15 \\cdot 3$. On note souvent $15 \\mid 45$.","steps":["Test de division : $45 / 15 = 3$ entier.","Donc $15 \\mid 45$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000039';
UPDATE public.items SET explanation = '{"text_fr":"Le PGCD de deux entiers est le **plus grand diviseur commun**. Pour 12 et 18, on liste les diviseurs : 12 a {1, 2, 3, 4, 6, 12}, 18 a {1, 2, 3, 6, 9, 18}. Communs : {1, 2, 3, 6}. Maximum : 6. Donc $\\mathrm{pgcd}(12, 18) = 6$.","steps":["Lister les diviseurs communs.","Choisir le maximum : 6."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000003a';
UPDATE public.items SET explanation = '{"text_fr":"Algorithme d''Euclide pour PGCD(36, 24) : $36 = 24 \\cdot 1 + 12$, puis $24 = 12 \\cdot 2 + 0$. Le **dernier reste non nul** est 12. Donc $\\mathrm{pgcd}(36, 24) = 12$. L''algorithme d''Euclide est plus rapide que lister les diviseurs.","steps":["Divisions successives : $36 = 24 + 12$, $24 = 12 \\cdot 2$.","Dernier reste non nul = 12."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000003b';
UPDATE public.items SET explanation = '{"text_fr":"**Transitivité de la divisibilité** : si $a \\mid b$ et $b \\mid c$, alors $a \\mid c$. Démonstration : $b = a k_1$ et $c = b k_2 = a (k_1 k_2)$, donc $a$ divise $c$ avec quotient $k_1 k_2$. Cette propriété fonde toute l''arithmétique des entiers.","steps":["Hypothèse : $b = ak_1$, $c = bk_2$.","Donc $c = a(k_1 k_2)$ : $a \\mid c$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000003c';
UPDATE public.items SET explanation = '{"text_fr":"Division euclidienne : $100 = 7 \\cdot 14 + 2$, donc le reste est 2. On vérifie : $7 \\cdot 14 = 98$, et $100 - 98 = 2$. Le reste est toujours dans $[0, 7[$ pour une division par 7.","steps":["$100 = 7 \\cdot 14 + r$ avec $0 \\le r < 7$.","$r = 100 - 98 = 2$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000003d';
UPDATE public.items SET explanation = '{"text_fr":"Le **principe fondamental de la dynamique** (2ème loi de Newton) s''écrit $\\sum \\vec F_{ext} = m \\vec a$ : la somme vectorielle des forces extérieures appliquées à un solide est égale au produit de sa masse par son accélération. C''est la pierre angulaire de la mécanique classique.","steps":["Énoncé : $\\sum \\vec F = m \\vec a$.","Force = masse × accélération."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000003e';
UPDATE public.items SET explanation = '{"text_fr":"Application directe du PFD : $F = ma$. Avec $m = 5$ kg et $a = 2$ m/s², on obtient $F = 5 \\cdot 2 = 10$ N. L''unité Newton se définit précisément ainsi : 1 N = force qui donne 1 m/s² à 1 kg.","steps":["PFD : $F = ma$.","$F = 5 \\cdot 2 = 10$ N."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000003f';
UPDATE public.items SET explanation = '{"text_fr":"Le poids d''un objet est la force gravitationnelle exercée par la Terre : $P = mg$. Avec $m = 2$ kg et $g = 10$ m/s² (valeur approchée), $P = 2 \\cdot 10 = 20$ N. Le poids est dirigé verticalement vers le bas.","steps":["Formule : $P = mg$.","$P = 2 \\cdot 10 = 20$ N."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000040';
UPDATE public.items SET explanation = '{"text_fr":"**3ème loi de Newton (action-réaction)** : si A exerce une force $\\vec F_{A \\to B}$ sur B, alors B exerce sur A la force opposée $\\vec F_{B \\to A} = -\\vec F_{A \\to B}$ — même intensité (5 N), même droite d''action, sens opposé. Les deux forces s''appliquent sur deux corps différents.","steps":["Loi : forces opposées et de même intensité.","Si A pousse B avec 5 N, B pousse A avec 5 N en sens contraire."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000041';
UPDATE public.items SET explanation = '{"text_fr":"Sur un plan incliné sans frottement, la composante du poids parallèle au plan vaut $P \\sin\\alpha = mg\\sin\\alpha$. Le PFD selon l''axe du plan donne $ma = mg\\sin\\alpha$, soit $a = g\\sin\\alpha$. Avec $g = 10$ m/s² et $\\alpha = 30°$ ($\\sin 30° = 0{,}5$) : $a = 10 \\cdot 0{,}5 = 5$ m/s². **L''accélération est indépendante de la masse.**","steps":["PFD selon le plan : $mg\\sin\\alpha = ma$.","$a = g\\sin\\alpha = 5$ m/s²."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000042';
UPDATE public.items SET explanation = '{"text_fr":"Pour un circuit RLC série, la période propre est $T_0 = 2\\pi\\sqrt{LC}$. Application : $LC = 1 \\cdot 10^{-5} = 10^{-5}$, $\\sqrt{LC} = 10^{-2{,}5} \\approx 3{,}162 \\cdot 10^{-3}$ s. $T_0 = 2\\pi \\cdot 3{,}162 \\cdot 10^{-3} \\approx 19{,}87 \\cdot 10^{-3}$ s = 19,87 ms.","steps":["Formule : $T_0 = 2\\pi\\sqrt{LC}$.","$\\sqrt{10^{-5}} \\approx 3{,}16 \\cdot 10^{-3}$.","$T_0 \\approx 19{,}87$ ms."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000043';
UPDATE public.items SET explanation = '{"text_fr":"Le régime **pseudo-périodique** apparaît quand la résistance $R$ est faible par rapport à la résistance critique $R_c = 2\\sqrt{L/C}$. Concrètement : oscillations amorties — le système oscille en perdant progressivement de l''énergie par effet Joule. Si $R = 0$ (idéal), oscillations entretenues sans amortissement.","steps":["Pseudo-périodique : $R < R_c = 2\\sqrt{L/C}$.","Oscillations amorties."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000044';
UPDATE public.items SET explanation = '{"text_fr":"Le régime **apériodique** apparaît quand $R > R_c$. La résistance domine, et le système retourne à l''équilibre **sans osciller** mais lentement (exponentiellement). Si on cherche le retour le plus rapide possible sans oscillation, on choisit $R = R_c$ (régime critique).","steps":["Apériodique : $R > R_c$.","Pas d''oscillation, retour exponentiel lent."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000045';
UPDATE public.items SET explanation = '{"text_fr":"En régime libre (sans générateur), un RLC série dissipe son énergie initiale dans la résistance $R$ par effet Joule : $P = R i^2$. L''énergie totale (capacité + bobine) **décroît** au cours du temps jusqu''à zéro. C''est ce qui distingue le RLC libre d''un LC idéal (qui oscillerait indéfiniment).","steps":["Effet Joule : $P = R i^2 > 0$.","Énergie totale décroît vers 0."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000046';
UPDATE public.items SET explanation = '{"text_fr":"Pour une onde progressive, la longueur d''onde $\\lambda$ et la période $T$ sont liées par la célérité $v$ via $\\lambda = vT$. Application : $\\lambda = 200 \\cdot 0{,}002 = 0{,}4$ m. C''est la distance parcourue par l''onde pendant une période.","steps":["Formule : $\\lambda = vT$.","$\\lambda = 200 \\cdot 2 \\cdot 10^{-3} = 0{,}4$ m."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000047';
UPDATE public.items SET explanation = '{"text_fr":"Une onde transporte de l''**énergie** (et de la quantité de mouvement) sans transport net de matière. Les particules du milieu oscillent autour de leur position d''équilibre, mais ne se déplacent pas globalement avec l''onde. C''est ce qui distingue une onde d''un courant de matière.","steps":["Onde = propagation d''une perturbation.","Énergie transportée, matière reste sur place."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000048';
UPDATE public.items SET explanation = '{"text_fr":"La fréquence est l''inverse de la période : $f = 1/T$. Application : $f = 1/(2 \\cdot 10^{-3}) = 500$ Hz. C''est le nombre d''oscillations complètes par seconde. Unité : hertz (Hz).","steps":["$f = 1/T$.","$f = 1/0{,}002 = 500$ Hz."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000049';
UPDATE public.items SET explanation = '{"text_fr":"À célérité $v$ constante (déterminée par le milieu), la relation $\\lambda = v/f$ implique que doubler $f$ divise $\\lambda$ par 2. C''est inversement proportionnel : plus la fréquence est haute, plus la longueur d''onde est courte. Vérification : si $\\lambda = v/f$ et $f \\to 2f$, alors $\\lambda \\to v/(2f) = \\lambda/2$.","steps":["$\\lambda = v/f$.","$f \\to 2f \\Rightarrow \\lambda \\to \\lambda/2$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000004a';
UPDATE public.items SET explanation = '{"text_fr":"Pour une onde sonore dans l''air à 1000 Hz : $\\lambda = v/f = 340/1000 = 0{,}34$ m = 34 cm. Pour mémoire : les sons audibles (20 Hz à 20 kHz) ont des longueurs d''onde de 17 m (graves) à 1,7 cm (aigus). C''est pourquoi les graves diffractent autour des obstacles courants, pas les aigus.","steps":["$\\lambda = v/f = 340/1000$.","$\\lambda = 0{,}34$ m."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000004b';
UPDATE public.items SET explanation = '{"text_fr":"La diffraction est marquée quand la taille de l''ouverture $a$ est de l''**ordre de la longueur d''onde** $\\lambda$. Si $\\lambda \\ll a$ (lumière à travers une porte), la diffraction est négligeable. Si $\\lambda \\approx a$ (lumière à travers une fente fine, ou son audible à travers une porte), elle devient visible. Si $\\lambda \\gg a$, l''onde ne passe pas (ou passe sans direction privilégiée).","steps":["Régime de diffraction : $\\lambda \\sim a$.","Trop petit : pas d''effet. Trop grand : opacité."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000004c';
UPDATE public.items SET explanation = '{"text_fr":"La période et la fréquence sont liées par $T = 1/f$. Pour $f = 500$ Hz : $T = 1/500 = 0{,}002$ s = 2 ms. Plus la fréquence est haute, plus la période est courte. Conversion utile : 1 ms = $10^{-3}$ s.","steps":["$T = 1/f$.","$T = 1/500 = 2 \\cdot 10^{-3}$ s = 2 ms."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000004d';
UPDATE public.items SET explanation = '{"text_fr":"La **demi-vie** $T_{1/2}$ est le temps au bout duquel la moitié des noyaux d''un échantillon se sont désintégrés. C''est une caractéristique propre à chaque isotope, indépendante de la quantité initiale. Pour le carbone-14 : $T_{1/2} = 5730$ ans ; pour l''iode-131 : 8 jours.","steps":["Définition : moitié désintégrée à $t = T_{1/2}$.","Caractéristique de l''isotope."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000004e';
UPDATE public.items SET explanation = '{"text_fr":"Au bout de $n$ demi-vies, l''activité est divisée par $2^n$. Au bout de 2 demi-vies : divisée par $2^2 = 4$. Application : $1000 / 4 = 250$ Bq. Au bout de 3 demi-vies : divisée par 8 (125 Bq), etc.","steps":["Loi : $A(nT_{1/2}) = A_0 / 2^n$.","$1000 / 4 = 250$ Bq."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000004f';
UPDATE public.items SET explanation = '{"text_fr":"Une **désintégration alpha** émet une particule $\\alpha$ identique à un noyau d''hélium 4 : 2 protons + 2 neutrons, soit $_2^4 He$. Le noyau père perd 2 unités de numéro atomique (Z) et 4 unités de nombre de masse (A). Caractéristique des noyaux lourds (uranium, radium, etc.).","steps":["$\\alpha = _2^4 He$ (noyau d''hélium).","Z diminue de 2, A de 4."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000050';
UPDATE public.items SET explanation = '{"text_fr":"La loi de désintégration radioactive s''écrit $N(t) = N_0 e^{-\\lambda t}$ où $\\lambda$ est la constante de désintégration (homogène à un inverse de temps). C''est une décroissance exponentielle, caractéristique des phénomènes de mort aléatoire. La demi-vie est $T_{1/2} = \\ln 2 / \\lambda$.","steps":["Décroissance exponentielle : $N(t) = N_0 e^{-\\lambda t}$.","Lien : $T_{1/2} = \\ln 2 / \\lambda$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000051';
UPDATE public.items SET explanation = '{"text_fr":"La constante de temps d''un circuit RC est $\\tau = RC$, homogène à un temps. Application : $\\tau = 10^3 \\cdot 10^{-5} = 10^{-2}$ s = 10 ms. C''est la durée caractéristique de la charge ou décharge — à $t = \\tau$, on a atteint 63% du régime établi.","steps":["$\\tau = RC$.","$\\tau = 10^3 \\cdot 10^{-5} = 0{,}01$ s = 10 ms."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000052';
UPDATE public.items SET explanation = '{"text_fr":"À $t = 5\\tau$, l''expression $1 - e^{-5} \\approx 1 - 0{,}007 = 0{,}993$ donne 99,3% — convention courante : on considère le régime établi à $5\\tau$. C''est le critère pratique pour dire « le condensateur est chargé ».","steps":["$1 - e^{-5} \\approx 0{,}993$.","Convention : régime établi à $5\\tau$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000053';
UPDATE public.items SET explanation = '{"text_fr":"À $t = \\tau$, $u_C(\\tau) = E(1 - e^{-1}) = E \\cdot 0{,}632$. Donc à $\\tau$, on est à **63%** du régime final. C''est un repère universel pour tout système exponentiel du premier ordre.","steps":["$1 - e^{-1} \\approx 0{,}632$.","À $\\tau$, charge à 63%."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000054';
UPDATE public.items SET explanation = '{"text_fr":"Décharge d''un condensateur : $u_C(t) = U_0 e^{-t/\\tau}$. À $t = \\tau$, $u_C = 10 \\cdot e^{-1} \\approx 10 \\cdot 0{,}368 = 3{,}68$ V. C''est le pendant de la charge : à $\\tau$, il reste 37% de la tension initiale.","steps":["Décharge : $u(t) = U_0 e^{-t/\\tau}$.","$u(\\tau) = 10 \\cdot 0{,}368 \\approx 3{,}68$ V."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000055';
UPDATE public.items SET explanation = '{"text_fr":"La constante de temps RL est $\\tau = L/R$, distincte de la constante RC ($\\tau = RC$). Application : $\\tau = 0{,}1 / 100 = 10^{-3}$ s = 1 ms. La self ralentit l''établissement du courant ; plus $L$ est grande ou $R$ petite, plus le courant met de temps à s''établir.","steps":["$\\tau = L/R$ (distinct de RC).","$\\tau = 0{,}1/100 = 1$ ms."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000056';
UPDATE public.items SET explanation = '{"text_fr":"En régime continu établi, le courant $i$ est constant donc $di/dt = 0$, et $u_L = L \\, di/dt = 0$. La bobine se comporte comme un fil court-circuit en régime continu permanent — distinction cruciale entre régime transitoire (où $u_L \\ne 0$) et permanent ($u_L = 0$).","steps":["Régime continu établi : $i$ constant, $di/dt = 0$.","$u_L = L \\, di/dt = 0$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000057';
UPDATE public.items SET explanation = '{"text_fr":"La constante de temps d''un circuit RL série est $\\tau = L/R$. Attention au piège : pour RC, c''est $\\tau = RC$ (avec multiplication) ; pour RL, c''est $L/R$ (avec division). Mémoriser les deux séparément.","steps":["RL : $\\tau = L/R$ (division).","RC : $\\tau = RC$ (multiplication)."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000058';
UPDATE public.items SET explanation = '{"text_fr":"En régime forcé, l''amplitude des oscillations est maximale quand la fréquence d''excitation $f$ coïncide avec la **fréquence propre** $f_0$ du système — c''est la **résonance**. Pour un RLC série, $f_0 = 1/(2\\pi\\sqrt{LC})$. La résonance est le mécanisme derrière les ponts qui s''effondrent et les radios qui captent une station.","steps":["Résonance à $f = f_0$.","Amplitude maximale."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000059';
UPDATE public.items SET explanation = '{"text_fr":"Plus la résistance (amortissement) est grande, moins le système accumule d''énergie au voisinage de $f_0$, donc le pic de résonance est **plus large et plus aplati** (faible facteur de qualité Q). À l''inverse, faible amortissement = pic aigu et étroit (haute sélectivité).","steps":["Amortissement $\\nearrow$ → pic plus aplati.","Faible $Q$ = peu sélectif."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000005a';
UPDATE public.items SET explanation = '{"text_fr":"**AM = Amplitude Modulation**. On module l''amplitude d''une porteuse haute fréquence par le signal informatif basse fréquence. La fréquence et la phase de la porteuse restent inchangées ; seule l''amplitude varie au rythme du signal modulant. Système historique de la radio AM.","steps":["AM module l''amplitude.","Fréquence/phase porteuse fixes."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000005b';
UPDATE public.items SET explanation = '{"text_fr":"Le spectre d''un signal AM contient : la fréquence porteuse $f_p$, et deux **bandes latérales** symétriques autour de $f_p$ ($f_p - f_s$ et $f_p + f_s$ pour un signal modulant à $f_s$). L''information est dans les bandes latérales.","steps":["Spectre AM = porteuse + 2 bandes latérales.","Bandes à $f_p \\pm f_s$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000005c';
UPDATE public.items SET explanation = '{"text_fr":"En chute libre depuis le repos, la hauteur de chute en un temps $t$ est $h = \\frac{1}{2} g t^2$. Application : $h = 0{,}5 \\cdot 10 \\cdot 4 = 20$ m. C''est l''archétype du MRUA (mouvement rectiligne uniformément accéléré).","steps":["MRUA : $h = \\frac{1}{2}gt^2$.","$h = 5 \\cdot 4 = 20$ m."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000005d';
UPDATE public.items SET explanation = '{"text_fr":"Sans frottement, un projectile soumis à la seule gravité a une trajectoire **parabolique** : mouvement rectiligne uniforme horizontalement + chute libre verticalement. Les deux mouvements sont indépendants ; leur composition donne la parabole. Galilée, premier à formuler ce résultat.","steps":["Composition : MRU horizontal + MRUA vertical.","Trajectoire parabolique."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000005e';
UPDATE public.items SET explanation = '{"text_fr":"En chute libre depuis le repos, la vitesse à l''instant $t$ est $v = gt$. Application : $v = 10 \\cdot 2 = 20$ m/s. À 2 s, l''objet a atteint 20 m/s = 72 km/h — l''accélération de la gravité s''accumule rapidement.","steps":["$v = gt$.","$v = 10 \\cdot 2 = 20$ m/s."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000005f';
UPDATE public.items SET explanation = '{"text_fr":"Pour un projectile lancé à angle $\\alpha$ avec vitesse $v_0$, la **portée** sur sol horizontal est $R = \\dfrac{v_0^2 \\sin(2\\alpha)}{g}$. Application avec $\\alpha = 45°$ : $\\sin(90°) = 1$, donc $R = v_0^2/g = 400/10 = 40$ m. **L''angle 45° maximise la portée** (puisque $\\sin 2\\alpha = 1$ y est maximal).","steps":["Formule : $R = v_0^2 \\sin(2\\alpha)/g$.","À 45° : $R = v_0^2/g = 40$ m."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000060';
UPDATE public.items SET explanation = '{"text_fr":"Entre deux plaques planes parallèles distantes de $d$ et soumises à une tension $U$, le champ électrique uniforme entre elles vaut $E = U/d$. Application : $E = 200 / 0{,}02 = 10\\,000$ V/m = $10^4$ V/m. Direction : de la plaque + vers la plaque −.","steps":["Formule : $E = U/d$.","$E = 200/0{,}02 = 10^4$ V/m."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000061';
UPDATE public.items SET explanation = '{"text_fr":"Convention en physique : le **champ électrique va de la plaque positive vers la plaque négative**. C''est la direction dans laquelle une charge positive serait poussée. Pour un électron (charge négative), la force est dans le sens opposé au champ : de − vers +.","steps":["Champ $\\vec E$ : de + vers −.","Sens du déplacement d''une charge + libre."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000062';
UPDATE public.items SET explanation = '{"text_fr":"La force exercée par un champ électrique sur une charge ponctuelle $q$ est $\\vec F = q \\vec E$. Pour $q > 0$, $\\vec F$ a la même direction que $\\vec E$ ; pour $q < 0$ (électron), $\\vec F$ est dans le sens opposé. C''est la définition même du champ électrique.","steps":["Force = charge × champ : $\\vec F = q\\vec E$.","Sens dépend du signe de $q$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000063';
UPDATE public.items SET explanation = '{"text_fr":"La **force de Lorentz magnétique** sur une charge $q$ animée de vitesse $\\vec v$ dans un champ magnétique $\\vec B$ est $\\vec F = q \\vec v \\wedge \\vec B$ (produit vectoriel). Sa direction est perpendiculaire au plan formé par $\\vec v$ et $\\vec B$, déterminée par la règle de la main droite.","steps":["Loi : $\\vec F = q\\vec v \\wedge \\vec B$.","Direction perpendiculaire à $(\\vec v, \\vec B)$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000064';
UPDATE public.items SET explanation = '{"text_fr":"Si $\\vec v$ est **parallèle** à $\\vec B$, le produit vectoriel $\\vec v \\wedge \\vec B = \\vec 0$ (puisque deux vecteurs colinéaires ont un produit vectoriel nul). Donc la force magnétique est nulle. Une charge se déplaçant le long des lignes de champ ne subit aucune force magnétique.","steps":["$\\vec v \\parallel \\vec B \\Rightarrow \\vec v \\wedge \\vec B = \\vec 0$.","Force magnétique nulle."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000065';
UPDATE public.items SET explanation = '{"text_fr":"La période d''un pendule simple aux petites oscillations est $T = 2\\pi\\sqrt{L/g}$. Application : $T = 2\\pi\\sqrt{1/10} = 2\\pi \\cdot 0{,}316 \\approx 1{,}99$ s. Indépendante de la masse et (pour petits angles) de l''amplitude — propriété remarquable découverte par Galilée.","steps":["$T = 2\\pi\\sqrt{L/g}$.","$T = 2\\pi \\cdot 0{,}316 \\approx 1{,}99$ s."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000066';
UPDATE public.items SET explanation = '{"text_fr":"Aux petites oscillations, la période d''un pendule simple **ne dépend que de $L$ (longueur) et de $g$ (gravité locale)**. Indépendante de la masse (Galilée) et indépendante de l''amplitude (isochronisme). Aux grandes amplitudes, l''isochronisme se brise — la période croît avec l''amplitude.","steps":["Petites oscillations : $T$ dépend de $L, g$ seuls.","Pas de la masse, pas (peu) de l''amplitude."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000067';
UPDATE public.items SET explanation = '{"text_fr":"Si on quadruple $L$, la période devient $T'' = 2\\pi\\sqrt{4L/g} = 2 \\cdot 2\\pi\\sqrt{L/g} = 2T$ — période **doublée**. La proportionnalité $T \\propto \\sqrt{L}$ fait que multiplier $L$ par $k^2$ multiplie $T$ par $k$.","steps":["$T \\propto \\sqrt{L}$.","$L \\to 4L \\Rightarrow T \\to 2T$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000068';
UPDATE public.items SET explanation = '{"text_fr":"L''énergie cinétique vaut $E_c = \\dfrac{1}{2} m v^2$. Application : $E_c = 0{,}5 \\cdot 2 \\cdot 9 = 9$ J. Unité : Joule (J = kg·m²/s²). Note : doubler $v$ quadruple $E_c$ — la vitesse intervient au carré.","steps":["$E_c = \\frac{1}{2}mv^2$.","$E_c = 0{,}5 \\cdot 2 \\cdot 9 = 9$ J."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000069';
UPDATE public.items SET explanation = '{"text_fr":"L''énergie potentielle de pesanteur vaut $E_p = mgh$ (avec référentiel au sol). Application : $E_p = 1 \\cdot 10 \\cdot 10 = 100$ J. Cette énergie est convertible en cinétique lors d''une chute libre.","steps":["$E_p = mgh$.","$E_p = 100$ J."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000006a';
UPDATE public.items SET explanation = '{"text_fr":"**Conservation de l''énergie mécanique** : en l''absence de frottements, $E_m = E_c + E_p$ se conserve. Pendant la chute, $E_p$ se transforme en $E_c$, mais leur somme reste constante. Système conservatif.","steps":["Sans frottement : $E_m = E_c + E_p = \\mathrm{cste}$.","Échange réversible $E_p \\leftrightarrow E_c$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000006b';
UPDATE public.items SET explanation = '{"text_fr":"Par conservation : $\\frac{1}{2} m v^2 = mgh$, soit $v = \\sqrt{2gh}$. La masse se simplifie. Application : $v = \\sqrt{2 \\cdot 10 \\cdot 5} = \\sqrt{100} = 10$ m/s. Tous les objets atteignent la même vitesse à hauteur de chute égale (sans frottements) — Galilée encore.","steps":["Conservation : $mgh = \\frac{1}{2}mv^2$.","$v = \\sqrt{2gh} = \\sqrt{100} = 10$ m/s."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000006c';
UPDATE public.items SET explanation = '{"text_fr":"Définition : $pH = -\\log_{10}[H_3O^+]$ avec $[H_3O^+]$ en mol/L. Application : $pH = -\\log(10^{-4}) = -(-4) = 4$. Plus $[H_3O^+]$ est grand, plus le pH est petit (échelle inverse).","steps":["$pH = -\\log[H_3O^+]$.","$pH = -\\log(10^{-4}) = 4$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000006d';
UPDATE public.items SET explanation = '{"text_fr":"Une solution est acide si pH < 7, neutre si pH = 7, basique si pH > 7 (à 25°C). Pour pH = 2, c''est nettement acide. Plus précisément, l''acidité augmente quand le pH diminue — un pH 1 est 10 fois plus acide qu''un pH 2.","steps":["pH < 7 = acide (à 25°C).","pH = 2 → acide."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000006e';
UPDATE public.items SET explanation = '{"text_fr":"À 25°C, $pH = 7$ correspond exactement à la **neutralité** : $[H_3O^+] = [OH^-] = 10^{-7}$ mol/L. Ces concentrations sont liées par le produit ionique de l''eau $K_e = [H_3O^+][OH^-] = 10^{-14}$. À d''autres températures, le pH neutre n''est pas exactement 7.","steps":["pH = 7 ⟺ $[H_3O^+] = [OH^-]$.","À 25°C : neutralité."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000006f';
UPDATE public.items SET explanation = '{"text_fr":"Inverse de la définition du pH : $[H_3O^+] = 10^{-pH}$. Application : $[H_3O^+] = 10^{-3}$ mol/L = 0,001 mol/L. Cette inversion est utile pour passer du pH (mesuré) à la concentration (utilisée dans les calculs d''équilibre).","steps":["$[H_3O^+] = 10^{-pH}$.","$10^{-3}$ mol/L."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000070';
UPDATE public.items SET explanation = '{"text_fr":"Pour un titrage acide fort / base forte à 25°C, la réaction est $H_3O^+ + OH^- \\to 2H_2O$, et au point d''équivalence on n''a que de l''eau et un sel neutre — donc **pH = 7**. C''est un repère universel pour ce type de titrage.","steps":["Acide fort + base forte : équivalence neutre.","pH = 7 à 25°C."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000071';
UPDATE public.items SET explanation = '{"text_fr":"À la **demi-équivalence** d''un titrage d''acide faible HA par une base forte, on a $[A^-] = [HA]$ (la moitié de l''acide a été transformée en base conjuguée). L''équation d''Henderson-Hasselbalch $pH = pK_a + \\log([A^-]/[HA])$ donne alors $\\log(1) = 0$, donc $pH = pK_a$. Méthode pratique pour mesurer un $pK_a$.","steps":["Demi-équivalence : $[A^-] = [HA]$.","Henderson : $pH = pK_a$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000072';
UPDATE public.items SET explanation = '{"text_fr":"Un indicateur coloré change de couleur sur une plage de pH d''environ **1 unité de pH** centrée sur son $pK_i$. Pour qu''il soit utilisable dans un titrage, son $pK_i$ doit être proche du pH à l''équivalence.","steps":["Plage de virage : $\\approx 1$ unité de pH.","Centre sur le $pK_i$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000073';
UPDATE public.items SET explanation = '{"text_fr":"La **vitesse instantanée** d''une réaction est la dérivée de la concentration par rapport au temps (en valeur absolue) : $v(t) = \\left|\\dfrac{d[A]}{dt}\\right|$. C''est la pente de la tangente à la courbe $[A](t)$. La vitesse moyenne sur $\\Delta t$ est différente : $\\Delta[A]/\\Delta t$.","steps":["Vitesse instantanée = dérivée temporelle.","$v = |d[A]/dt|$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000074';
UPDATE public.items SET explanation = '{"text_fr":"Un **catalyseur** abaisse l''énergie d''activation et accélère la réaction sans être consommé ni modifier l''équilibre final. C''est la méthode privilégiée pour augmenter la vitesse sans perturber le rendement. Augmenter $T$ accélère aussi, mais peut décaler l''équilibre. Diluer ralentit en général.","steps":["Catalyseur \\to $E_a$ baisse \\to vitesse augmente.","Pas de consommation, pas d''effet sur l''équilibre."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000075';
UPDATE public.items SET explanation = '{"text_fr":"Le **temps de demi-réaction** $t_{1/2}$ est le temps au bout duquel la moitié du réactif initial a été consommée — c''est-à-dire $[A](t_{1/2}) = [A]_0/2$. Pour une cinétique d''ordre 1, $t_{1/2} = \\ln 2 / k$ (constante).","steps":["$t_{1/2}$ : moitié du réactif consommée.","Ordre 1 : $t_{1/2} = \\ln 2 / k$."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000076';
UPDATE public.items SET explanation = '{"text_fr":"Une réaction **réversible** peut se dérouler dans les deux sens (notation $\\rightleftharpoons$). L''état final est un **équilibre** où réaction directe et inverse se compensent. Toutes les réactions chimiques sont en principe réversibles, mais certaines ont un équilibre tellement déplacé qu''on les traite comme totales.","steps":["Réversible : deux sens, notation $\\rightleftharpoons$.","État final : équilibre dynamique."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000077';
UPDATE public.items SET explanation = '{"text_fr":"À l''**équilibre dynamique**, les vitesses des réactions directe et inverse sont égales — pas zéro, mais compensées. Microscopiquement, des molécules réagissent dans les deux sens en permanence ; macroscopiquement, les concentrations sont constantes.","steps":["Vitesses directe = inverse.","Équilibre dynamique, pas statique."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000078';
UPDATE public.items SET explanation = '{"text_fr":"Le critère d''évolution dit : si $Q_r < K$, le système doit augmenter $Q_r$ pour atteindre $K$, donc évolue dans le **sens direct** (formation de produits, qui figurent au numérateur de $Q_r$). Ce critère est universel pour prédire le sens d''évolution.","steps":["$Q_r < K$ → évolue pour augmenter $Q_r$.","Sens direct (formation de produits)."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000079';
UPDATE public.items SET explanation = '{"text_fr":"La constante $K$ d''une réaction ne dépend que de la **température**. Elle est indépendante des concentrations initiales, du volume, de la pression, ou de la présence d''un catalyseur. Cette propriété fait de $K$ une caractéristique thermodynamique pure de la réaction.","steps":["$K$ dépend uniquement de $T$.","Pas de $[X]_0$, pas de $V$, pas de catalyseur."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000007a';
UPDATE public.items SET explanation = '{"text_fr":"Un $K$ très grand signifie que le rapport produits/réactifs à l''équilibre est très grand — autrement dit, la réaction directe est très favorisée et l''équilibre est très déplacé vers les produits. À l''inverse, un $K$ très petit favorise les réactifs.","steps":["$K$ grand : produits dominent à l''équilibre.","Réaction directe favorisée."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000007b';
UPDATE public.items SET explanation = '{"text_fr":"Pour la pile Daniell, la fem standard est $\\Delta E^\\circ = E^\\circ(\\text{cathode}) - E^\\circ(\\text{anode}) = E^\\circ(Cu^{2+}/Cu) - E^\\circ(Zn^{2+}/Zn) = 0{,}34 - (-0{,}76) = 1{,}10$ V. Le cuivre, plus noble, est cathode ; le zinc, moins noble, est anode.","steps":["$\\Delta E^\\circ = E_{cathode} - E_{anode}$.","$\\Delta E^\\circ = 0{,}34 + 0{,}76 = 1{,}10$ V."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000007c';
UPDATE public.items SET explanation = '{"text_fr":"Dans la pile Daniell, l''**anode** est l''électrode où a lieu l''oxydation : $Zn \\to Zn^{2+} + 2e^-$. Le zinc, moins noble que le cuivre (potentiel plus faible), perd ses électrons. Convention : la borne négative de la pile est l''anode.","steps":["Zn moins noble → s''oxyde.","Anode = borne négative."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000007d';
UPDATE public.items SET explanation = '{"text_fr":"Une pile est un dispositif qui transforme l''énergie **chimique** (réaction d''oxydoréduction spontanée) en énergie **électrique** (courant dans le circuit extérieur). C''est l''inverse de l''électrolyse, qui consomme de l''énergie électrique pour forcer une réaction non spontanée.","steps":["Pile : chimique → électrique.","Réaction redox spontanée."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000007e';
UPDATE public.items SET explanation = '{"text_fr":"L''**estérification** est la réaction entre un acide carboxylique R-COOH et un alcool R''-OH, donnant un ester R-COO-R'' et de l''eau. Notation : $RCOOH + R''OH \\rightleftharpoons RCOOR'' + H_2O$. Réaction célèbre pour produire les arômes des fruits et fleurs.","steps":["Réactifs : acide + alcool.","Produits : ester + eau."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-00000000007f';
UPDATE public.items SET explanation = '{"text_fr":"L''estérification est **limitée** (équilibre, rendement plafonné autour de 67% pour mélange équimolaire) et **lente** (heures à température ambiante sans catalyseur). Ces deux caractéristiques en font une réaction industrielle qu''on accélère par catalyseur acide et qu''on déplace en éliminant l''eau.","steps":["Limitée : équilibre, rendement ~67%.","Lente : nécessite catalyseur ou chauffage."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000080';
UPDATE public.items SET explanation = '{"text_fr":"Pour augmenter le rendement d''une estérification, le catalyseur n''aide pas (il accélère seulement). Le levier efficace est d''**éliminer l''eau** au fur et à mesure (loi de Le Chatelier) : retirer un produit déplace l''équilibre vers la formation de plus de produit. Méthode pratique : Dean-Stark.","steps":["Catalyseur : vitesse seule.","Élimination de l''eau : déplace l''équilibre (Le Chatelier)."]}'::jsonb WHERE id = '44444444-aaaa-0000-0000-000000000081';

COMMIT;
